// Verify the HMAC signature before anything else looks at this payload.
//
// This endpoint is on the public internet and will be found. The signature is
// what stops it being fed fabricated reviews, and the timestamp window stops a
// captured payload being replayed indefinitely.
const crypto = require('crypto');

const secret = $vars.TRIAGE_WEBHOOK_SECRET;
if (!secret) {
  throw new Error('TRIAGE_WEBHOOK_SECRET is not set; refusing to process unverified input');
}

const headers = $input.item.json.headers || {};
const signature = headers['x-jupiterp-signature'] || '';
const timestamp = headers['x-jupiterp-timestamp'] || '';
const raw = JSON.stringify($input.item.json.body);

const age = Math.abs(Math.floor(Date.now() / 1000) - parseInt(timestamp, 10));
if (!timestamp || Number.isNaN(age) || age > 300) {
  throw new Error('timestamp outside the 5 minute tolerance window');
}

const expected = 'sha256=' + crypto
  .createHmac('sha256', secret)
  .update(timestamp + '.' + raw)
  .digest('hex');

// Constant time: a plain === leaks the signature one byte at a time.
const a = Buffer.from(expected);
const b = Buffer.from(signature);
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
  throw new Error('bad signature');
}

return { json: $input.item.json.body };

// Normalise the model's reply into a decision the callback can send.
//
// This node carries the whole guarantee. The Gemini node exposes a boolean
// jsonOutput rather than schema-constrained decoding, so nothing upstream
// enforces that `decision` is one of three words -- the contract is stated in
// the system prompt and checked here. Anything unreadable, out of enum, or
// missing a field becomes "escalate". A moderation pipeline that guesses when
// it cannot read its own input eventually publishes something nobody approved.
const review = $('Verify signature').item.json;
const raw = $input.item.json;

function coerce(value) {
  if (value === null || value === undefined) return null;
  if (typeof value === 'object' && !Array.isArray(value)) return value;
  if (typeof value !== 'string') return null;
  // Models emit fenced blocks even when asked not to.
  const text = value.trim()
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/, '');
  try {
    const parsed = JSON.parse(text);
    return typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : null;
  } catch (e) {
    return null;
  }
}

// The shape depends on the node's simplify setting and version, so try the
// places the payload is known to land rather than assuming one.
let parsed = null;
for (const candidate of [raw.output, raw.message, raw.content, raw.text, raw]) {
  const object = coerce(candidate);
  if (object && 'decision' in object) { parsed = object; break; }
  if (!parsed && object) parsed = object;
}

const allowed = ['approve', 'reject', 'escalate'];
let decision = 'escalate';
let reason = 'classifier output could not be read';
let categories = [];
let confidence = 0;

if (parsed) {
  if (allowed.includes(parsed.decision)) {
    decision = parsed.decision;
    reason = typeof parsed.reason === 'string' ? parsed.reason : '';
  } else {
    reason = `decision was not one of ${allowed.join('/')}: ${JSON.stringify(parsed.decision)}`;
  }
  if (Array.isArray(parsed.categories)) {
    categories = parsed.categories.filter((c) => typeof c === 'string');
  }
  const c = Number(parsed.confidence);
  confidence = Number.isFinite(c) && c >= 0 && c <= 1 ? c : 0;
}

// Belt and braces. The API enforces this too, but a review carrying flagged
// categories must never ride an approve path out of here.
if (categories.length > 0 && decision === 'approve') {
  decision = 'escalate';
  reason = 'flagged categories present: ' + categories.join(', ');
}

// A confident-looking approval with no confidence value is a parse failure
// wearing a decision's clothes.
if (decision === 'approve' && confidence === 0) {
  decision = 'escalate';
  reason = 'approve returned without a usable confidence value';
}

return {
  json: {
    review_id: review.review_id,
    action: decision,
    confidence,
    categories,
    reason,
    policy_version: review.policy_version,
    model: 'models/gemini-2.0-flash-001',
  },
};
